"""RC truck autopilot: steer through the slalom cones from the truck's two range sensors.

Sample code for the RC truck project. Speeds in m/s, angles in degrees.
v3 raised MAX_SPEED to 2.2 m/s: 5.9 s laps, but it clipped a cone (it was trained on 1.5 m/s laps).
"""

MAX_SPEED = 2.2        # v3; v2 ran at 1.5 and finished clean in 7.4 s
MAX_STEER = 28.0
CONE_GAP_M = 1.2


def clamp(x, lo, hi):
    return max(lo, min(hi, x))


def steer(left_m, right_m):
    """Turn toward the side with more room. Equal room: straight ahead."""
    room = right_m - left_m
    return clamp(room / CONE_GAP_M * MAX_STEER, -MAX_STEER, MAX_STEER)


def speed(steer_deg):
    """Slow down in sharp turns: v1 rolled over at 2.1 m/s on a hard turn."""
    turn = abs(steer_deg) / MAX_STEER
    return MAX_SPEED * (1.0 - 0.45 * turn)


def control(left_m, right_m):
    s = steer(left_m, right_m)
    return {"steer_deg": round(s, 1), "speed_ms": round(speed(s), 2)}


if __name__ == "__main__":
    for left, right in [(0.6, 0.6), (0.3, 0.9), (1.0, 0.2)]:
        print(left, right, control(left, right))

"""Quadcopter hover test: thrust to weight and hover time for each frame version.

Sample code for the quadcopter project. Grams, millimetres, minutes. Same numbers as the design's analysis.
"""

VERSIONS = {
    5: {"props_in": 5, "wheelbase_mm": 220, "mass_g": 389, "thrust_per_motor_g": 1375, "hover_min": 10.9},
    6: {"props_in": 7, "wheelbase_mm": 220, "mass_g": 404, "thrust_per_motor_g": 1725, "hover_min": 14.4},
    7: {"props_in": 7, "wheelbase_mm": 320, "mass_g": 601, "thrust_per_motor_g": 2253, "hover_min": 13.5},
}
MOTORS = 4


def thrust_to_weight(v):
    return MOTORS * v["thrust_per_motor_g"] / v["mass_g"]


def ready_to_fly(v, clearance_mm):
    """Props must clear each other, and 2x thrust to weight is the least for a stable hover."""
    return clearance_mm > 0 and thrust_to_weight(v) >= 2.0


if __name__ == "__main__":
    for n, v in VERSIONS.items():
        print(f"v{n}: {v['props_in']} in props, thrust {thrust_to_weight(v):.1f}x weight, {v['hover_min']} min hover")

"""Small CNN for CIFAR-10: three conv blocks, then a two-layer head."""

import torch
import torch.nn as nn


def conv_block(cin: int, cout: int) -> list[nn.Module]:
    return [nn.Conv2d(cin, cout, 3, padding=1), nn.BatchNorm2d(cout), nn.ReLU(), nn.MaxPool2d(2)]


class SmallCNN(nn.Module):
    def __init__(self, num_classes: int = 10) -> None:
        super().__init__()
        self.features = nn.Sequential(*conv_block(3, 32), *conv_block(32, 64), *conv_block(64, 128), nn.Flatten())
        self.head = nn.Sequential(nn.Linear(128 * 4 * 4, 128), nn.ReLU(), nn.Linear(128, num_classes))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.head(self.features(x))
